@@ -142,200 +142,231 @@ button {

 .control-panel {
   padding: 42px;
   border-right: 1px solid var(--line);
 }

 .step-heading {
   margin-bottom: 28px;
   display: flex;
   gap: 17px;
   align-items: flex-start;
 }

 .step-heading > span {
   width: 33px;
   height: 33px;
   border-radius: 50%;
   background: #e9f5fa;
   color: var(--blue-dark);
   display: grid;
   place-items: center;
   flex: 0 0 auto;
   font-size: 11px;
   font-weight: 800;
 }

 .step-heading h2,
 .preview-heading h2 {
   margin: 0;
   font-size: 22px;
   letter-spacing: -0.025em;
 }

 .step-heading p {
   margin: 7px 0 0;
   color: var(--muted);
