   line-height: 1.45;
 }

 .field {
   margin-bottom: 18px;
   display: block;
 }

 .field > span {
   margin-bottom: 8px;
   display: flex;
   justify-content: space-between;
   color: #344248;
   font-size: 12px;
   font-weight: 700;
 }

 .field small {
   color: #8c999e;
   font-weight: 400;
 }

 .field input,
 .field textarea {
   width: 100%;
   border: 1px solid #ccd5d5;
   border-radius: 11px;
   outline: none;
   background: #fbfcfa;
   color: var(--ink);
   font-size: 14px;
   transition: border-color 140ms ease, box-shadow 140ms ease;
 }

 .field input {
   height: 46px;
   padding: 0 13px;
 }

 .field textarea {
   padding: 12px 13px;
   line-height: 1.45;
   resize: vertical;
 }

 .field input:focus,
 .field textarea:focus {
   border-color: var(--blue);
   box-shadow: 0 0 0 3px rgb(86 173 216 / 13%);
 }

 .field em {
   margin-top: 5px;
   display: block;
   color: #889397;
   font-size: 11px;
   font-style: normal;
 }

 .url-field input {
   height: 52px;
 }

+.url-coverage {
+  margin: -6px 0 19px;
+  color: var(--muted);
+  font-size: 11px;
+  line-height: 1.5;
+}
+
+.url-coverage summary {
+  width: fit-content;
+  cursor: pointer;
+  color: #526368;
+  font-weight: 700;
+}
+
+.url-coverage p {
+  margin: 9px 0 5px;
+}
+
+.url-coverage code {
+  padding: 1px 4px;
+  border-radius: 4px;
+  background: #eff3f2;
+  color: #35484e;
+  font-size: 10px;
+}
+
+.url-coverage small {
+  color: #728287;
+  font-size: 10px;
+}
+
 .primary-button,
 .download-button {
   border: 0;
   cursor: pointer;
   display: flex;
   align-items: center;
   justify-content: center;
   font-weight: 750;
 }

 .primary-button {
   width: 100%;
   height: 52px;
   border-radius: 12px;
   background: var(--ink);
   color: white;
   gap: 10px;
 }

 .primary-button span {
   font-size: 20px;
 }

 .primary-button:disabled,
 .download-button:disabled {
   cursor: wait;
   opacity: 0.6;
 }

 .status-message {
   margin-top: 15px;
   padding: 11px 12px;
   border-radius: 9px;
   background: #f5f7f5;
   color: var(--muted);
   display: flex;
   gap: 9px;
   font-size: 12px;
   line-height: 1.45;
 }

 .status-message.error {
   background: #fff2ef;
   color: #90483d;
 }

 .status-message.success {
   background: #eff7ec;
   color: #496a40;
 }

 .status-dot {
   width: 7px;
   height: 7px;
   margin-top: 5px;
   border-radius: 50%;
   background: currentColor;
   flex: 0 0 auto;
 }

 .divider {
   height: 1px;
   margin: 31px 0 9px;
   background: var(--line);
 }

 .editor-toggle {
   width: 100%;
   padding: 17px 0;
   border: 0;
   background: transparent;
   cursor: pointer;
   display: flex;
   justify-content: space-between;
   font-size: 15px;
   font-weight: 700;
 }

 .editor-toggle b {
   margin-right: 12px;
   color: var(--blue-dark);
   font-size: 11px;
 }

 .editor-note {
   margin: 0 0 20px;
   color: var(--muted);
   font-size: 12px;
   line-height: 1.5;
 }

 .field-row {
   display: grid;
   grid-template-columns: 1fr 1fr;
   gap: 12px;
 }

 .upload-button {
   min-height: 44px;
   padding: 0 15px;
diff --git a/src/components/ad-generator.tsx b/src/components/ad-generator.tsx
index d82036f..b2b2074 100644
--- a/src/components/ad-generator.tsx
+++ b/src/components/ad-generator.tsx
@@ -75,200 +75,209 @@ export function AdGenerator() {
         body: JSON.stringify({ url }),
       });
       const payload = (await response.json()) as {
         product?: ProductCreative;
         error?: string;
       };
       if (!response.ok || !payload.product) {
         throw new Error(payload.error || "Unable to read that product page.");
       }

       setProduct(payload.product);
       setShowEditor(true);
       setStatus({
         kind: "success",
         message: "Product facts loaded from Minimalist. Review the copy before exporting.",
       });
     } catch (error) {
       setProduct({ ...EMPTY_PRODUCT, sourceUrl: url });
       setShowEditor(true);
       setStatus({
         kind: "error",
         message:
           error instanceof Error
             ? `${error.message} You can still edit the fields and upload a product image manually.`
             : "Unable to load the product. Continue with the manual fields below.",
       });
     }
   };

   const uploadProductImage = (event: ChangeEvent<HTMLInputElement>) => {
     const file = event.target.files?.[0];
     if (!file) return;
     updateProduct("imageUrl", URL.createObjectURL(file));
   };

   const downloadCreative = async () => {
     if (!creativeRef.current) return;
     setIsExporting(true);
     try {
       const dataUrl = await toPng(creativeRef.current, {
         cacheBust: true,
         canvasWidth: 1080,
         canvasHeight: 1080,
         pixelRatio: 1,
       });
       const link = document.createElement("a");
       link.download = `${product.title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-meta-square.png`;
       link.href = dataUrl;
       link.click();
       setStatus({ kind: "success", message: "Your 1080 × 1080 PNG has been downloaded." });
     } catch {
       setStatus({
         kind: "error",
         message: "The preview could not be exported. Try loading the product again.",
       });
     } finally {
       setIsExporting(false);
     }
   };

   return (
     <main>
       <header className="site-header">
         <a className="wordmark" href="#top" aria-label="Minimalist Ad Studio home">
           M<span>·</span>AD STUDIO
         </a>
         <div className="surface-tabs" aria-label="Product surfaces">
           <span className="surface-tab active">Generate</span>
           <span className="surface-tab upcoming">Review <small>next</small></span>
         </div>
         <span className="prototype-label">Internal prototype</span>
       </header>

       <section className="hero" id="top">
         <p className="kicker">Evidence-led creative production</p>
         <h1>Turn a product page into a ready-to-review ad.</h1>
         <p className="hero-copy">
           Real product imagery. Page-supported copy. A reusable layout designed for Minimalist.
         </p>
       </section>

       <section className="studio-grid">
         <aside className="control-panel">
           <div className="step-heading">
             <span>01</span>
             <div>
               <h2>Choose a product</h2>
               <p>Paste any public product page from beminimalist.co.</p>
             </div>
           </div>

           <label className="field url-field">
             <span>Product URL</span>
             <input
               type="url"
               value={url}
               onChange={(event) => setUrl(event.target.value)}
               placeholder="https://beminimalist.co/products/…"
             />
           </label>
+          <details className="url-coverage">
+            <summary>Which URLs are supported?</summary>
+            <p>
+              Use a live <b>beminimalist.co</b> URL containing <code>/products/…</code>.
+              Direct and collection-prefixed product links both work. Collection, search,
+              homepage, other-domain, removed, and unpublished-product URLs do not.
+            </p>
+            <small>Coverage check: all 20 reviewed product pages loaded successfully.</small>
+          </details>
           <button className="primary-button" type="button" onClick={loadProduct} disabled={status.kind === "loading"}>
             {status.kind === "loading" ? "Reading product…" : "Build this ad"}
             <span aria-hidden="true">→</span>
           </button>

           <div className={`status-message ${status.kind}`} role="status">
             <span className="status-dot" />
             {status.message}
           </div>

           <div className="divider" />

           <button
             className="editor-toggle"
             type="button"
             onClick={() => setShowEditor((current) => !current)}
             aria-expanded={showEditor}
           >
             <span><b>02</b> Review and edit</span>
             <span aria-hidden="true">{showEditor ? "−" : "+"}</span>
           </button>

           {showEditor ? (
             <div className="editor-fields">
               <p className="editor-note">
                 These fields are prefilled from the page. Treat edits as marketer-owned copy.
               </p>
               <TextField label="Product name" value={product.title} maxLength={58} onChange={(value) => updateProduct("title", value)} />
               <TextField label="Eyebrow" value={product.eyebrow} maxLength={38} onChange={(value) => updateProduct("eyebrow", value)} />
               <TextArea label="Headline" value={product.headline} maxLength={72} hint="Use a line break to control wrapping." onChange={(value) => updateProduct("headline", value)} />
               <TextArea label="Supporting copy" value={product.supportingCopy} maxLength={165} onChange={(value) => updateProduct("supportingCopy", value)} />
               <TextField label="Proof points" value={product.badges} maxLength={56} onChange={(value) => updateProduct("badges", value)} />
               <TextField label="Formula line" value={product.detailLine} maxLength={54} onChange={(value) => updateProduct("detailLine", value)} />

               <div className="field-row">
                 <TextField label="Size" value={product.size} maxLength={14} onChange={(value) => updateProduct("size", value)} />
                 <TextField label="Price" value={product.price} maxLength={14} onChange={(value) => updateProduct("price", value)} />
               </div>
               <TextField label="Original price (optional)" value={product.compareAtPrice ?? ""} maxLength={14} onChange={(value) => updateProduct("compareAtPrice", value)} />
               <TextField label="Call to action" value={product.cta} maxLength={28} onChange={(value) => updateProduct("cta", value)} />
               <label className="upload-button">
                 <input type="file" accept="image/png,image/jpeg,image/webp" onChange={uploadProductImage} />
                 <span>Replace product image</span>
               </label>
             </div>
           ) : null}
         </aside>

         <section className="preview-panel">
           <div className="preview-heading">
             <div>
               <span className="placement-label">META · SQUARE</span>
               <h2>Creative preview</h2>
             </div>
             <span className="dimensions">1080 × 1080</span>
           </div>

           <CreativePreview product={product} ref={creativeRef} />

           <div className="preview-actions">
             <div className="draft-note">
               <span>DRAFT</span>
               <p>Generated from page facts. Final review is still required.</p>
             </div>
             <button
               className="download-button"
               type="button"
               onClick={downloadCreative}
               disabled={isExporting || !canExport}
               title={canExport ? "Download this draft" : "Add a product name, headline, supporting copy, and image first"}
             >
               {isExporting ? "Preparing PNG…" : "Download PNG"}
               <DownloadIcon />
             </button>
           </div>
         </section>
       </section>

       <footer>
         <span>Minimalist Ad Studio · v0.1</span>
         <span>Next: score this creative against the documented review standard.</span>
       </footer>
     </main>
   );
 }

 function TextField({
   label,
   value,
   maxLength,
   onChange,
 }: {
   label: string;
   value: string;
   maxLength: number;
   onChange: (value: string) => void;
 }) {
   return (
     <label className="field">
       <span>{label} <small>{value.length}/{maxLength}</small></span>

